def reference(date) -> bool:
    # Rule 1: non-empty string; Rule 4: format mm-dd-yyyy (10 chars, digits + dashes)
    if not isinstance(date, str):
        return False
    if len(date) == 0:
        return False
    if len(date) != 10:
        return False
    if date[2] != "-" or date[5] != "-":
        return False
    m_s, d_s, y_s = date[:2], date[3:5], date[6:]
    if len(m_s) != 2 or len(d_s) != 2 or len(y_s) != 4:
        return False
    if not (m_s.isdigit() and d_s.isdigit() and y_s.isdigit()):
        return False
    m = int(m_s)
    d = int(d_s)
    # Rule 3
    if not 1 <= m <= 12:
        return False
    # Rule 2
    if not 1 <= d <= _max_day(m):
        return False
    return True

@given(
    m=st.sampled_from([1, 3, 5, 7, 8, 10, 12]),
    y=st.integers(min_value=0, max_value=9999),
)
def test_property_31_day_months_accept_30_and_31_reject_32(m, y):
    y_s = f"{y:04d}"
    assert valid_date(f"{m:02d}-30-{y_s}") is True
    assert valid_date(f"{m:02d}-31-{y_s}") is True
    assert valid_date(f"{m:02d}-32-{y_s}") is False
